def lookup(sku: str) -> Product:
    """Return a product by SKU, raising KeyError with a helpful message."""
    try:
        return CATALOG[sku]
    except KeyError:
        raise KeyError(f"unknown sku {sku!r}; {len(CATALOG)} products in catalogue") from None


def needs_reorder(sku: str, on_hand: int) -> bool:
    """True when stock has fallen to or below the product reorder level."""
    return on_hand <= lookup(sku).reorder_level


def by_category(category: str) -> list[Product]:
    """All products in a category, catalogue order."""
    return [p for p in CATALOG.values() if p.category == category]
